This C++17 implementation uses the historical haybales.in and haybales.out interface.

```cpp
#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("haybales.in");
    std::ofstream out("haybales.out");
    int n, q;
    if (!(in >> n >> q)) return 1;
    std::vector<long long> x(n);
    for (auto &v : x) in >> v;
    std::sort(x.begin(), x.end());
    for (int i = 0; i < q; ++i) {
        long long a, b;
        in >> a >> b;
        auto left = std::lower_bound(x.begin(), x.end(), a);
        auto right = std::upper_bound(x.begin(), x.end(), b);
        out << right - left << '\n';
    }
}
```

The following C++17 implementation reads citystate.in and writes one integer to citystate.out.

```cpp
#include <fstream>
#include <string>
#include <vector>
int code(const std::string &s) {
    return 26 * (s[0] - 'A') + (s[1] - 'A');
}
int main() {
    std::ifstream in("citystate.in");
    std::ofstream out("citystate.out");
    int n;
    if (!(in >> n)) return 1;
    std::vector<std::vector<long long>> count(676, std::vector<long long>(676));
    long long answer = 0;
    for (int i = 0; i < n; ++i) {
        std::string city, state;
        in >> city >> state;
        int a = code(city), b = code(state);
        if (a == b) continue;
        answer += count[b][a];
        ++count[a][b];
    }
    out << answer << '\n';
}
```

Reviewed C++17 numerical-input correction, preserving the original directed-search algorithm and moocast.in/moocast.out:

```cpp
#include <algorithm>
#include <fstream>
#include <vector>
#include <cassert>
#include <cctype>
#include <string>
using namespace std;
string independent_decimal_square(const string& value) {
    const size_t length = value.size();
    vector<int> digits(2 * length + 2);
    for (size_t i = 0; i < length; ++i) {
        int carry = 0;
        for (size_t j = 0; j < length; ++j) {
            const int v = digits[i + j] + (value[length - 1 - i] - '0') * (value[length - 1 - j] - '0') + carry;
            digits[i + j] = v % 10; carry = v / 10;
        }
        size_t pos = i + length;
        while (carry) { const int v = digits[pos] + carry; digits[pos] = v % 10; carry = v / 10; ++pos; }
    }
    while (digits.size() > 1 && digits.back() == 0) digits.pop_back();
    string result; for (auto i = digits.rbegin(); i != digits.rend(); ++i) result.push_back(static_cast<char>('0' + *i));
    return result;
}
struct IndependentRadius {
    int kind; // -1 negative,0 coincident-only,1 exact finite decimal square,2 above all possible distances
    string square;
    size_t denominator_zeros;
    bool includes(long long squared_distance) const {
        if (kind == -1) return false;
        if (squared_distance == 0 || kind == 2) return true;
        if (kind == 0) return false;
        string threshold = to_string(squared_distance);
        threshold.append(denominator_zeros, '0');
        return threshold.size() < square.size() || (threshold.size() == square.size() && threshold <= square);
    }
};
IndependentRadius independent_radius(const string& token) {
    size_t pos = 0; bool negative = false;
    if (token[pos] == '+' || token[pos] == '-') { negative = token[pos] == '-'; ++pos; }
    const size_t exponent_pos = token.find_first_of("eE", pos);
    const size_t end = exponent_pos == string::npos ? token.size() : exponent_pos;
    string coefficient; long long fractional_digits = 0; bool fraction = false;
    for (; pos < end; ++pos) {
        if (token[pos] == '.') { assert(!fraction); fraction = true; continue; }
        assert(isdigit(static_cast<unsigned char>(token[pos])));
        coefficient.push_back(token[pos]); if (fraction) ++fractional_digits;
    }
    assert(!coefficient.empty());
    long long exponent = 0;
    if (exponent_pos != string::npos) {
        pos = exponent_pos + 1; bool minus = false;
        if (token[pos] == '+' || token[pos] == '-') { minus = token[pos] == '-'; ++pos; }
        assert(pos < token.size()); const long long cap = static_cast<long long>(token.size()) + 100;
        for (; pos < token.size(); ++pos) { assert(isdigit(static_cast<unsigned char>(token[pos]))); const int digit = token[pos] - '0'; exponent = exponent > (cap - digit) / 10 ? cap : exponent * 10 + digit; }
        if (minus) exponent = -exponent;
    }
    const size_t first = coefficient.find_first_not_of('0');
    if (first == string::npos) return {0, "0", 0};
    if (negative) return {-1, "0", 0};
    coefficient.erase(0, first);
    long long scale = fractional_digits - exponent;
    while (coefficient.back() == '0') { coefficient.pop_back(); --scale; }
    const long long integer_digits = static_cast<long long>(coefficient.size()) - scale;
    if (integer_digits < 1) return {0, "0", 0};
    if (integer_digits > 5) return {2, "0", 0};
    int whole = 0;
    for (long long i = 0; i < integer_digits; ++i) whole = 10 * whole + (i < static_cast<long long>(coefficient.size()) ? coefficient[static_cast<size_t>(i)] - '0' : 0);
    if (whole >= 35356) return {2, "0", 0};
    string square = independent_decimal_square(coefficient);
    if (scale < 0) { square.append(static_cast<size_t>(-2 * scale), '0'); return {1, square, 0}; }
    return {1, square, static_cast<size_t>(2 * scale)};
}
struct Cow { long long x, y; IndependentRadius radius; };
int main() {
    std::ifstream in("moocast.in");
    std::ofstream out("moocast.out");
    int n;
    if (!(in >> n)) return 1;
    std::vector<Cow> cows(n);
    for (auto &c : cows) {
        std::string power;
        if (!(in >> c.x >> c.y >> power)) return 1;
        c.radius = independent_radius(power);
        if (c.radius.kind < 0) return 1; // Physical radii are nonnegative; no printed numeric limit is assumed.
    }
    std::vector<std::vector<int>> edges(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long long dx = cows[i].x - cows[j].x;
            long long dy = cows[i].y - cows[j].y;
            long long distance2 = dx * dx + dy * dy;
            if (i != j && cows[i].radius.includes(distance2))
                edges[i].push_back(j);
        }
    }
    int best = 0;
    for (int start = 0; start < n; ++start) {
        std::vector<bool> seen(n, false);
        std::vector<int> stack{start};
        seen[start] = true;
        int reached = 1;
        while (!stack.empty()) {
            int v = stack.back();
            stack.pop_back();
            for (int next : edges[v]) {
                if (!seen[next]) {
                    seen[next] = true;
                    ++reached;
                    stack.push_back(next);
                }
            }
        }
        best = std::max(best, reached);
    }
    out << best << '\n';
}
